	recipe->texture_meters[HOUSE_MATERIAL_CARVED] = 0.6f;
	recipe->texture_meters[HOUSE_MATERIAL_LOG] = 2.0f;  // (along a log; round it the texture goes once, or half of it once: log_mapping)
	recipe->texture_meters[HOUSE_MATERIAL_ROOF_TIMBER] = 0.5f;  // (the old wood's fibers are coarse: at the varnished wood's 1.95 m, even at 1 m, it looked stretched)
	recipe->moss = 0.3f;
	recipe->lichen = 0.08f;
	recipe->width = 5.8f;
	recipe->depth = 9.5f;
