int house_preset_count(void)
{
	return (int)(sizeof(presets) / sizeof(presets[0]));
}

const char *house_preset_name(int index)
{
	return index >= 0 && index < house_preset_count() ? presets[index].name : NULL;
}

// A roof of wooden shingles: the shingle textures (data/props/textures),
// a repeat of five rows of them, a thinner roof than thatch's
void house_recipe_shingles(house_recipe_t *recipe)
{
	static const char *const maps[3] = { "color", "normal", "arm" };

	recipe->thatch = 0;
	for (int t = 0; t < 3; t++)
	{
		snprintf(recipe->textures[HOUSE_MATERIAL_ROOF][t], sizeof(recipe->textures[HOUSE_MATERIAL_ROOF][t]), "props/textures/house_roof_shingle_%s.png",
			maps[t]);
	}
	recipe->texture_meters[HOUSE_MATERIAL_ROOF] = SHINGLE_TEXTURE_METERS;
	recipe->roof_thickness = minimum_of(recipe->roof_thickness, 0.08f);
	// (on laths and rafters it sags less than thatch: sagging as much, the
	// slope came down onto the walls' tops, thin as it is)
	recipe->roof_sag = minimum_of(recipe->roof_sag, SHINGLE_SAG);
}

// A roof of slate: the slate textures, a repeat of twelve rows of them,
// thin
void house_recipe_slate(house_recipe_t *recipe)
{
	static const char *const maps[3] = { "color", "normal", "arm" };

	recipe->thatch = 0;
	for (int t = 0; t < 3; t++)
	{
		snprintf(recipe->textures[HOUSE_MATERIAL_ROOF][t], sizeof(recipe->textures[HOUSE_MATERIAL_ROOF][t]), "props/textures/house_roof_slate_%s.png", maps[t]);
	}
	recipe->texture_meters[HOUSE_MATERIAL_ROOF] = SLATE_TEXTURE_METERS;
	recipe->roof_thickness = minimum_of(recipe->roof_thickness, 0.06f);
}

// A roof of stone slabs (lauze): their textures, rows of about 27 cm, a
// thick roof
void house_recipe_lauze(house_recipe_t *recipe)
{
	static const char *const maps[3] = { "color", "normal", "arm" };

	recipe->thatch = 0;
	for (int t = 0; t < 3; t++)
	{
		snprintf(recipe->textures[HOUSE_MATERIAL_ROOF][t], sizeof(recipe->textures[HOUSE_MATERIAL_ROOF][t]), "props/textures/house_roof_lauze_%s.png", maps[t]);
	}
	recipe->texture_meters[HOUSE_MATERIAL_ROOF] = LAUZE_TEXTURE_METERS;
	recipe->roof_thickness = 0.1f;
	recipe->roof_sag = minimum_of(recipe->roof_sag, SHINGLE_SAG);
}

// Whether a preset's house is roofed in slate: dressed stone's always, a
// town house's or an inn's about two in five (by its name: the same
// preset, the same roof)
static bool preset_slated(const house_recipe_t *recipe, const char *name)
{
	uint32_t hash = 2166136261u;

	if (recipe->wall == HOUSE_WALL_STONE)
	{
		return true;
	}
	if (recipe->kind != HOUSE_KIND_TOWNHOUSE && recipe->kind != HOUSE_KIND_INN)
	{
		return false;
	}
	for (const char *c = name; *c != '\0'; c++)
	{
		hash = (hash ^ (uint32_t)(unsigned char)*c) * 16777619u;
	}
	return hash % 5u == 3u;
}

bool house_preset(house_recipe_t *recipe, const char *name)
{
	for (int i = 0; i < house_preset_count(); i++)
	{
		if (strcmp(presets[i].name, name) == 0)
		{
			recipe->kind = presets[i].kind;
			recipe->size = presets[i].size;
			house_recipe_apply_kind(recipe);
			presets[i].tweak(recipe);
			// (a reed roof: wooden shingles for now, the thatch put by
			// (thatch = 1 in a recipe still makes one)
			// (a hovel of rubble or logs: stone slabs, the rest of the
			// thatched ones shingles)
			if (recipe->thatch && recipe->kind == HOUSE_KIND_HOVEL && (recipe->wall == HOUSE_WALL_RUBBLE || recipe->wall == HOUSE_WALL_LOG))
			{
				house_recipe_lauze(recipe);
			}
			else if (recipe->thatch)
			{
				house_recipe_shingles(recipe);
			}
			else if (preset_slated(recipe, name))
			{
				house_recipe_slate(recipe);
			}
			// (a barn's big roof: its texture twice as large, the repeats
			// fewer over it)
			if (recipe->kind == HOUSE_KIND_BARN)
			{
				recipe->texture_meters[HOUSE_MATERIAL_ROOF] *= 2.0f;
			}
			snprintf(recipe->preset, sizeof(recipe->preset), "%s", name);
			return true;
		}
	}
	house_error("No preset '%s'", name);
	return false;
}

